package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.stock.*;
import com.intermarche.backoffice.domain.executing.*;
import com.intermarche.backoffice.engine.stock.*;
import io.quarkus.test.junit.QuarkusTest;
import io.quarkus.narayana.jta.QuarkusTransaction;
import io.restassured.response.Response;
import jakarta.inject.Inject;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.restassured.RestAssured.given;
@QuarkusTest
@jakarta.enterprise.inject.Typed(TraceabilityWorkflowTest.class)
class TraceabilityWorkflowTest extends MissionCoordinationTest {
 @Inject TemporalStockService stocks;
 record Stock(Long account,Long first,Long second,Long firstSegment,Long secondSegment){}
 Response quality(String token,String method,String path,Object body){var r=given().auth().oauth2(token).contentType("application/json");if(body!=null)r.body(body);var response=r.request(method,"/quality"+path);if(response.statusCode()>=400)System.out.println(path+" "+response.asString());return response;}
 Stock stock(){Long account=QuarkusTransaction.requiringNew().call(()->{var a=stocks.account(f.store(),f.product());stocks.adjust(a.id,f.location(),"initial",new BigDecimal("20"),com.intermarche.backoffice.domain.util.DateTimeProvider.now().minusMinutes(10));return a.id;});Long[] lots=new Long[2];Long[] segments=new Long[2];for(int n=0;n<2;n++){lots[n]=call(f.manager(),"POST","/manufacturer-lots",Map.of("storeId",f.store(),"productId",f.product(),"code","FAB-"+n,"useBy",LocalDate.now().plusDays(10+n*10).toString())).then().statusCode(200).extract().jsonPath().getLong("id");var rows=call(f.manager(),"GET","/products/"+f.product()+"/stock-segments?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().getList("$",Map.class);var source=rows.stream().filter(r->r.get("lotId")==null&&new BigDecimal(r.get("quantity").toString()).signum()>0).findFirst().orElseThrow();var result=call(f.manager(),"POST","/stock-segments/reclassify",Map.of("storeId",f.store(),"sourceId",((Number)source.get("id")).longValue(),"quantity",10,"quality","AVAILABLE","lotId",lots[n],"reason","Identification du lot reçu","requestKey",key(),"expectedRevision",source.get("revision"))).then().statusCode(200).extract();segments[n]=result.jsonPath().getLong("targetId");}return new Stock(account,lots[0],lots[1],segments[0],segments[1]);}
 void eq(int expected,BigDecimal actual){assertEquals(0,BigDecimal.valueOf(expected).compareTo(actual));}
 Map<String,Object> pick(Stock s){attach(f.tote());var c=command("PICK");c.putAll(Map.of("itemId",f.item(),"quantity",2,"toteCode",f.tote(),"stockSegmentId",s.secondSegment));command(c).then().statusCode(200);return c;}
 @Test void explicitLotFollowsPickingToteTransferReturnAndIdempotentReplay(){line();Stock s=stock();var picked=pick(s);command(picked).then().statusCode(200);attach(f.second());var move=command("MOVE_ITEM");move.putAll(Map.of("itemId",f.item(),"toteCode",f.tote(),"targetToteCode",f.second()));command(move).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{var state=PickedStockState.<PickedStockState>find("itemId",f.item()).firstResult();var a=PickedStockAllocation.<PickedStockAllocation>find("state=?1 and quantity>0",state).firstResult();assertEquals(s.second,a.holding.lot.id);assertEquals(f.second(),a.holding.support.code);eq(2,a.quantity);eq(8,StockSegments.balance(StockSegment.findById(s.secondSegment),com.intermarche.backoffice.domain.util.DateTimeProvider.now()));eq(20,StockMovement.<StockMovement>list("account.id",s.account).stream().map(m->m.quantity).reduce(BigDecimal.ZERO,BigDecimal::add));});var returned=command("RETURN_ITEM");returned.putAll(Map.of("itemId",f.item(),"toteCode",f.second()));command(returned).then().statusCode(200);command(returned).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{eq(10,StockSegments.balance(StockSegment.findById(s.secondSegment),com.intermarche.backoffice.domain.util.DateTimeProvider.now()));assertEquals(0,PickedStockAllocation.count("state.itemId=?1 and quantity>0",f.item()));});}
 @Test void recallAfterPickingFindsTheToteNotifiesAndBlocksNormalTransferUntilRelease(){line();Stock s=stock();pick(s);attach(f.second());var hold=quality(f.manager(),"POST","/cases",Map.of("storeId",f.store(),"productId",f.product(),"lotId",s.second,"kind","RECALL","reason","Avis fournisseur sur le lot FAB-1","requestKey",key(),"includeUnknownLots",true)).then().statusCode(200).extract();long holdId=hold.jsonPath().getLong("id");assertEquals(f.tote(),hold.path("trace.goods[0].toteCode"));var move=command("MOVE_ITEM");move.putAll(Map.of("itemId",f.item(),"toteCode",f.tote(),"targetToteCode",f.second()));command(move).then().statusCode(409);QuarkusTransaction.requiringNew().run(()->assertEquals(f.tote(),PickedItem.<PickedItem>findById(f.item()).loadedTote.tote.code));quality(f.picker(),"POST","/cases/"+holdId+"/release",Map.of("storeId",f.store(),"requestKey",key(),"expectedRevision",hold.<String>path("revision"),"reason","Contrôle terminé")).then().statusCode(403);var release=Map.of("storeId",f.store(),"requestKey",key(),"expectedRevision",hold.<String>path("revision"),"reason","Avis fournisseur levé après contrôle");quality(f.manager(),"POST","/cases/"+holdId+"/release",release).then().statusCode(200);quality(f.manager(),"POST","/cases/"+holdId+"/release",release).then().statusCode(200);command(move).then().statusCode(200);}
 @Test void expiryRemovesOnlyPromiseCapacityAndRecallKeepsPhysicalTotals(){
  line();Stock s=stock();QuarkusTransaction.requiringNew().run(()->{ManufacturerLot lot=ManufacturerLot.findById(s.first);lot.useBy=LocalDate.now().minusDays(1);});
  QuarkusTransaction.requiringNew().run(()->{var timeline=stocks.availability(s.account,null,com.intermarche.backoffice.domain.util.DateTimeProvider.now());eq(20,timeline.physical);eq(10,timeline.periods.getFirst().availableToPromise);});
  quality(f.manager(),"POST","/cases",Map.of("storeId",f.store(),"productId",f.product(),"lotId",s.second,"kind","BLOCK","reason","Contrôle du second lot","requestKey",key(),"includeUnknownLots",false)).then().statusCode(200);
  QuarkusTransaction.requiringNew().run(()->{var timeline=stocks.availability(s.account,null,com.intermarche.backoffice.domain.util.DateTimeProvider.now());eq(20,timeline.physical);eq(0,timeline.periods.getFirst().availableToPromise);});
 }
 @Test void fefoChoosesEarlierExpiryAndPickedGoodsAreNotPromisedAgain(){
  line();Stock s=stock();attach(f.tote());var picked=command("PICK");picked.putAll(Map.of("itemId",f.item(),"quantity",2,"toteCode",f.tote()));command(picked).then().statusCode(200);
  QuarkusTransaction.requiringNew().run(()->{var allocation=PickedStockAllocation.<PickedStockAllocation>find("state.itemId=?1 and quantity>0",f.item()).firstResult();assertEquals(s.first,allocation.holding.lot.id);var timeline=stocks.availability(s.account,null,com.intermarche.backoffice.domain.util.DateTimeProvider.now());eq(20,timeline.physical);eq(18,timeline.periods.getFirst().availableToPromise);});
 }
 @Test void targetedInventoryIsVisibleToOperatorAndBlindSnapshotNeverLeaks(){
  line();Stock stock=stock();var body=Map.of("storeId",f.store(),"buildingId",f.building(),"scopeKind","BAY","area","Z","aisle","A","bay","1","start",java.time.LocalDateTime.now().plusHours(1).toString(),"end",java.time.LocalDateTime.now().plusHours(2).toString(),"requestKey",key(),"blind",true);
  var created=given().auth().oauth2(f.manager()).contentType("application/json").body(body).post("/inventories").then().statusCode(200).extract();long inventory=created.jsonPath().getLong("id");assertEquals("BAY",created.path("scopeKind"));assertNotNull(created.path("targets[0].expectedQuantity"));
  given().auth().oauth2(f.manager()).contentType("application/json").body(body).post("/inventories").then().statusCode(200).body("id",org.hamcrest.Matchers.is((int)inventory));
  var operator=given().auth().oauth2(f.picker()).get("/inventories/"+inventory+"?storeId="+f.store()).then().statusCode(200).extract();assertNull(operator.path("targets[0].expectedQuantity"));assertNull(operator.path("targets[0].lotCode"));
  given().auth().oauth2(f.picker()).contentType("application/json").body(body).post("/inventories").then().statusCode(403);
  given().auth().oauth2(f.manager()).get("/inventories/scopes?storeId="+f.store()+"&buildingId="+f.building()).then().statusCode(200).body("bays[0].bay",org.hamcrest.Matchers.is("1"));
  QuarkusTransaction.requiringNew().run(()->eq(20,stocks.availability(stock.account,null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical));
 }
 @Test void internalSupplyPreservesManufacturerLotThroughReceiptAndBothReopenings(){
  line();Stock s=stock();Long[] refs=QuarkusTransaction.requiringNew().call(()->{var destination=new com.intermarche.backoffice.domain.store.StoreShelfLocation();destination.product=com.intermarche.backoffice.domain.order.Product.findById(f.product());destination.area="Z";destination.aisle="A";destination.unit="2";destination.elevation="1";destination.position="1";destination.persist();com.intermarche.backoffice.domain.store.Building.<com.intermarche.backoffice.domain.store.Building>findById(f.building()).locations.add(destination);var supply=stocks.planSupply(s.account,key(),f.location(),destination.id,BigDecimal.valueOf(3),com.intermarche.backoffice.domain.util.DateTimeProvider.now().plusHours(1));return new Long[]{supply.id,destination.id};});
  QuarkusTransaction.requiringNew().run(()->stocks.pick(refs[0],"trace-pick",BigDecimal.valueOf(3),com.intermarche.backoffice.domain.util.DateTimeProvider.now()));
  QuarkusTransaction.requiringNew().run(()->stocks.receive(refs[0],"trace-receive",BigDecimal.valueOf(3),com.intermarche.backoffice.domain.util.DateTimeProvider.now(),false));
  QuarkusTransaction.requiringNew().run(()->{var segment=StockSegment.<StockSegment>find("location.id=?1 and lot.id=?2",refs[1],s.first).firstResult();assertNotNull(segment);eq(3,StockSegments.balance(segment,com.intermarche.backoffice.domain.util.DateTimeProvider.now()));eq(20,stocks.availability(s.account,null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical);});
  QuarkusTransaction.requiringNew().run(()->stocks.reopen(refs[0],"undo-receive",false,com.intermarche.backoffice.domain.util.DateTimeProvider.now()));
  QuarkusTransaction.requiringNew().run(()->stocks.reopen(refs[0],"undo-pick",true,com.intermarche.backoffice.domain.util.DateTimeProvider.now()));
  QuarkusTransaction.requiringNew().run(()->{eq(10,StockSegments.balance(StockSegment.findById(s.firstSegment),com.intermarche.backoffice.domain.util.DateTimeProvider.now()));eq(20,stocks.availability(s.account,null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical);});
 }
 @Test void quarantiningPickedStockNotifiesItsMissionAndPreservesItsManufacturerIdentity(){
  line();Stock s=stock();pick(s);attach(f.second());var rows=call(f.manager(),"GET","/products/"+f.product()+"/stock-segments?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().getList("$",Map.class);var held=rows.stream().filter(r->f.tote().equals(r.get("supportCode"))&&new BigDecimal(r.get("quantity").toString()).signum()>0).findFirst().orElseThrow();
  call(f.manager(),"POST","/stock-segments/reclassify",Map.of("storeId",f.store(),"sourceId",((Number)held.get("id")).longValue(),"quantity",2,"quality","QUARANTINE","lotId",s.second,"supportId",held.get("supportId"),"reason","Emballage douteux dans le bac","requestKey",key(),"expectedRevision",held.get("revision"))).then().statusCode(200);
  var move=command("MOVE_ITEM");move.putAll(Map.of("itemId",f.item(),"toteCode",f.tote(),"targetToteCode",f.second()));command(move).then().statusCode(409);
  QuarkusTransaction.requiringNew().run(()->{var allocation=PickedStockAllocation.<PickedStockAllocation>find("state.itemId=?1 and quantity>0",f.item()).firstResult();assertEquals("QUARANTINE",allocation.holding.quality);assertEquals(s.second,allocation.holding.lot.id);assertTrue(com.intermarche.backoffice.domain.fieldops.FieldIncident.count("handlingOrder.id=?1 and kind='SAFETY'",f.order())>0);eq(20,stocks.availability(s.account,null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical);});
 }
 @Test void aCompleteToteMovedToAnotherBuildingKeepsItsLotAndCustomerAllocation(){line();Stock s=stock();pick(s);Long[] destination=QuarkusTransaction.requiringNew().call(()->{var store=com.intermarche.backoffice.domain.store.Store.<com.intermarche.backoffice.domain.store.Store>findById(f.store());var building=new com.intermarche.backoffice.domain.store.WarehouseBuilding();building.buildingCode="TRF-"+key().substring(0,8);building.persist();store.buildings.add(building);var buffer=new com.intermarche.backoffice.domain.store.Buffer();buffer.building=building;buffer.bufferCode="TRF-BUFFER";buffer.ambientCapacity=10;buffer.persist();var tote=PickedItem.<PickedItem>findById(f.item()).loadedTote;return new Long[]{buffer.id,tote.id,building.id};});var request=Map.of("storeId",f.store(),"toteId",destination[1],"bufferId",destination[0]);given().auth().oauth2(f.manager()).contentType("application/json").body(request).post("/store-operations/buffer-deposits").then().statusCode(200);given().auth().oauth2(f.manager()).contentType("application/json").body(request).post("/store-operations/buffer-deposits").then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{var allocation=PickedStockAllocation.<PickedStockAllocation>find("state.itemId=?1 and quantity>0",f.item()).firstResult();assertEquals(s.second,com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id(allocation.holding.lot));eq(2,StockSegments.balance(allocation.holding,com.intermarche.backoffice.domain.util.DateTimeProvider.now()));assertEquals(destination[2],com.intermarche.backoffice.domain.store.BaseLocation.findBuildingsByLocations(List.of(allocation.holding.location)).getFirst().id);eq(20,stocks.availability(s.account,null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical);assertEquals(2,StockMovement.count("account.id=?1 and reason='SUPPORT_TRANSFER'",s.account));});}


 @Test void identityLookupByCodeIsReadOnlyAndScopedToTheStore(){
  Long lot=call(f.manager(),"POST","/manufacturer-lots",Map.of("storeId",f.store(),"productId",f.product(),"code","LOOKUP-LOT")).then().statusCode(200).extract().jsonPath().getLong("id");
  call(f.picker(),"POST","/product-serials",Map.of("storeId",f.store(),"productId",f.product(),"lotId",lot,"code","LOOKUP-SERIAL","claimKey",key())).then().statusCode(200);
  String prefix="/products/"+f.product();
  call(f.picker(),"GET",prefix+"/manufacturer-lot?storeId="+f.store()+"&code=LOOKUP-LOT",null).then().statusCode(200).body("exists",org.hamcrest.Matchers.is(true)).body("lot.id",org.hamcrest.Matchers.equalTo(lot.intValue()));
  call(f.picker(),"GET",prefix+"/product-serial?storeId="+f.store()+"&code=LOOKUP-SERIAL",null).then().statusCode(200).body("exists",org.hamcrest.Matchers.is(true)).body("serial.lotId",org.hamcrest.Matchers.equalTo(lot.intValue()));
  for(String kind:List.of("manufacturer-lot","product-serial")){
   call(f.picker(),"GET",prefix+"/"+kind+"?storeId="+f.store()+"&code=UNKNOWN",null).then().statusCode(200).body("exists",org.hamcrest.Matchers.is(false));
   call(f.picker(),"GET",prefix+"/"+kind+"?storeId="+f.other()+"&code=LOOKUP-LOT",null).then().statusCode(403);
  }
  QuarkusTransaction.requiringNew().run(()->{assertEquals(1,ManufacturerLot.count("store.id",f.store()));assertEquals(1,ProductSerial.count("store.id",f.store()));});
 }
}
